import static org.junit.Assert.assertEquals;

public class AppVersionTest {

    @Test
    public void parseName_EmptyString_ReturnsNull() {
        String amiName = "";
        AppVersion parsedName = AppVersion.parseName(amiName);
        assertNull(parsedName);
    }

    @Test
    public void parseName_SimpleVersion_ReturnsParsedAppVersion() {
        String amiName = "1.2.3";
        AppVersion expected = new AppVersion("1.2.3");
        AppVersion parsedName = AppVersion.parseName(amiName);
        assertEquals(expected, parsedName);
    }

    @Test
    public void parseName_DelimitedVersion_ReturnsParsedAppVersion() {
        String amiName = "1.2.3-4";
        AppVersion expected = new AppVersion("1.2.3-4");
        AppVersion parsedName = AppVersion.parseName(amiName);
        assertEquals(expected, parsedName);
    }

    @Test
    public void parseName_Pattern_ReturnsParsedAppVersion() {
        String amiName = "v1.2.3";
        AppVersion expected = new AppVersion("v1.2.3");
        AppVersion parsedName = AppVersion.parseName(amiName);
        assertEquals(expected, parsedName);
    }

    @Test
    public void compareVersions_SameVersion_ReturnsZero() {
        AppVersion appVersion1 = new AppVersion("1.2.3");
        AppVersion appVersion2 = new AppVersion("1.2.3");
        int result = appVersion1.compareTo(appVersion2);
        assertEquals(0, result);
    }

